export function lettering(lines) {
    // Unmapped characters use the readable HTML heading instead of partial lettering.
    if (lines.some(line => [...line].some(char => !glyphs[char]))) return null;
    let scale = .105;
    for (const [row, line] of lines.entries()) {
        const chars = [...line];
        const extent = chars.slice(0, -1).reduce((width, char) => width + glyphs[char].width, 0)
            + (glyphs[chars.at(-1)]?.right || 0);
        if (extent) scale = Math.min(scale, (520 - row * 45) / extent);
    }
    const used = [...new Set(lines.join('').replaceAll(' ', ''))];
    const definitions = used.map((char, index) => `<path id="letter-live-${index}" d="${glyphs[char].outline}"/>`);
    const shapes = [];
    let count = 0;
    for (const [row, line] of lines.entries()) {
        let x = row * 45;
        let word = 0;
        for (const char of line) {
            const glyph = glyphs[char];
            if (char === ' ') {
                word++;
            } else {
                const id = `pen-live-${count++}`;
                const strokes = glyph.strokes.map(route => `<path class="pen-stroke" data-row="${row}" data-word="${word}" d="${route}" fill="none" stroke="white" stroke-width="230" stroke-linecap="round" stroke-linejoin="round"/>`);
                definitions.push(`<mask id="${id}" maskUnits="userSpaceOnUse" x="-150" y="-300" width="1200" height="1200">${strokes.join('')}</mask>`);
                shapes.push(`<use href="#letter-live-${used.indexOf(char)}" transform="translate(${x.toFixed(2)} ${78 + row * 110}) scale(${scale.toFixed(6)} ${(-scale).toFixed(6)})" fill="currentColor" mask="url(#${id})"/>`);
            }
            x += glyph.width * scale;
        }
    }
    return `<svg class="monostich-lettering" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 530 220" aria-hidden="true" focusable="false"><defs>${definitions.join('')}</defs>${shapes.join('')}</svg>`;
}
